parameters.functionCode:
// Extract user message and conversation history
const userMessage = $json.chatInput || $json.message || $json.userMessage || '';
const conversationHistory = $json.history || [];

// Generate sessionId if not provided (simple UUID v4 alternative)
const sessionId = $json.sessionId || 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
  const r = Math.random() * 16 | 0;
  const v = c === 'x' ? r : (r & 0x3 | 0x8);
  return v.toString(16);
});

// Get or initialize session state
let sessionState = $json.state || {
  intent: null, // Detected intent: 'whitelabel_migration', 'e2e_solution', 'unknown'
  intentConfidence: 0,
  subWorkflow: null, // Which workflow is handling this
  workflowState: {}, // State specific to the sub-workflow
  step: 0,
  complete: false
};

return {
  json: {
    userMessage,
    conversationHistory,
    sessionId,
    sessionState
  }
};

