parameters.functionCode:
const llmResponse = $json.message.content;

// Try to extract JSON from response
let intentData;
try {
  const jsonMatch = llmResponse.match(/\{[\s\S]*\}/);
  intentData = JSON.parse(jsonMatch[0]);
} catch (e) {
  // Fallback if parsing fails
  intentData = {
    intent: 'unknown',
    confidence: 0.0,
    reasoning: 'Failed to parse intent',
    clarificationNeeded: true,
    suggestedQuestion: 'I\'m not sure what you\'d like to do. Could you tell me more about what you\'re trying to accomplish?'
  };
}

// Update session state
const sessionState = $('Parse User Message').item.json.sessionState;
sessionState.intent = intentData.intent;
sessionState.intentConfidence = intentData.confidence;
sessionState.step = 1;

return {
  json: {
    intentData,
    sessionState,
    sessionId: $('Parse User Message').item.json.sessionId,
    userMessage: $('Parse User Message').item.json.userMessage,
    conversationHistory: $('Parse User Message').item.json.conversationHistory
  }
};

// Update session state with workflow response
const workflowResponse = $json;
const sessionState = $('Parse Intent Response').item.json.sessionState;

// Update workflow-specific state
sessionState.workflowState = workflowResponse.sessionState || {};
sessionState.subWorkflow = 'whitelabel_migration';
sessionState.complete = workflowResponse.complete || false;

return {
  json: {
    message: workflowResponse.message,
    sessionId: workflowResponse.sessionId,
    sessionState: sessionState,
    complete: workflowResponse.complete,
    intent: 'whitelabel_migration',
    progress: workflowResponse.progress,
    migrationId: workflowResponse.migrationId
  }
};

